insert into jdr.cards (id, name, data, created_by) values
  ('progeniture_araignee', $j$Progéniture araignée$j$, $j${"type": "Créature", "subtype": "Monstre", "supertypes": [], "image_url": "", "abilities": [], "creature": {"category": "Bête", "family": "Araignée", "level": 0, "groupDie": "D4", "group": "araignees", "hearts": 2, "armor": 0, "armorMagic": 0, "res": 0, "opres": "D4", "corps": 1, "esprit": 1, "charme": -2, "movement": "marche (sol, mur et plafond)", "speed": "proche (9 m)", "attacks": {"primary": "2 dégâts perforants", "secondary": "", "tertiary": ""}, "immuneAfflictions": "", "immuneDamage": "", "weakDamage": "", "abilities": [{"name": "Morsure empoisonnée", "text": "Lorsqu’une créature touchée par l’araignée n’était pas empoisonnée, l’araignée s’oppose à sa résistance. Si elle réussit, la cible gagne l’affliction Empoisonné et perd 2 points de vie par tour pendant 4 tours."}]}}$j$::jsonb, 'f43e9cf5-730e-4ede-9b15-1f267d7d7780'),
  ('araignee_loup', $j$Araignée loup$j$, $j${"type": "Créature", "subtype": "Monstre", "supertypes": [], "image_url": "", "abilities": [], "creature": {"category": "Bête", "family": "Araignée", "level": 1, "groupDie": "D4", "group": "araignees", "hearts": 3, "armor": 0, "armorMagic": 0, "res": 2, "opres": "D4", "corps": 2, "esprit": 1, "charme": -1, "movement": "marche (sol, mur et plafond)", "speed": "proche (9 m)", "attacks": {"primary": "4 dégâts perforants", "secondary": "", "tertiary": ""}, "immuneAfflictions": "", "immuneDamage": "", "weakDamage": "", "abilities": [{"name": "Morsure empoisonnée", "text": "Lorsqu’une créature touchée par l’araignée n’était pas empoisonnée, l’araignée s’oppose à sa résistance. Si elle réussit, la cible gagne l’affliction Empoisonné et perd 2 points de vie par tour pendant 4 tours."}]}}$j$::jsonb, 'f43e9cf5-730e-4ede-9b15-1f267d7d7780'),
  ('araignee_de_phase', $j$Araignée de phase$j$, $j${"type": "Créature", "subtype": "Monstre", "supertypes": [], "image_url": "", "abilities": [], "creature": {"category": "Bête", "family": "Araignée", "level": 2, "groupDie": "D4", "group": "araignees", "hearts": 3, "armor": 0, "armorMagic": 0, "res": 2, "opres": "D4", "corps": 2, "esprit": 1, "charme": -2, "movement": "marche (sol, mur et plafond)", "speed": "proche (9 m)", "attacks": {"primary": "6 dégâts perforants", "secondary": "", "tertiary": ""}, "immuneAfflictions": "", "immuneDamage": "", "weakDamage": "", "abilities": [{"name": "Morsure empoisonnée", "text": "Lorsqu’une créature touchée par l’araignée n’était pas empoisonnée, l’araignée s’oppose à sa résistance. Si elle réussit, la cible gagne l’affliction Empoisonné et perd 2 points de vie par tour pendant 4 tours."}, {"name": "Déphasage", "text": "Après une attaque, si l’araignée de phase n’est pas dans la toile de phase, elle s’oppose à la résistance de son adversaire. Si elle réussit, elle l’emmène dans la toile de phase.\nAu début de son tour, si l’araignée de phase est dans la toile de phase, elle peut la quitter puis jouer son tour normalement."}, {"name": "La toile de phase", "text": "Les araignées de phase tissent une toile magique qui crée une sorte de plan de poche. Il n’est pas rare que ces créatures piègent leur proie sur ce plan-toile. Si ça vous arrive, ayez du feu ou beaucoup de patience. — Elenvar Valtir, Veilleur de Clesasske"}]}}$j$::jsonb, 'f43e9cf5-730e-4ede-9b15-1f267d7d7780'),
  ('araignee_recluse', $j$Araignée recluse$j$, $j${"type": "Créature", "subtype": "Monstre", "supertypes": [], "image_url": "", "abilities": [], "creature": {"category": "Bête", "family": "Araignée", "level": 1, "groupDie": "D4", "group": "araignees", "hearts": 3, "armor": 0, "armorMagic": 0, "res": 1, "opres": "D4", "corps": 2, "esprit": 1, "charme": 0, "movement": "marche (sol, mur et plafond), fouissement", "speed": "proche (9 m)", "attacks": {"primary": "4 dégâts perforants", "secondary": "", "tertiary": ""}, "immuneAfflictions": "", "immuneDamage": "", "weakDamage": "", "abilities": [{"name": "Morsure empoisonnée", "text": "Lorsqu’une créature touchée par l’araignée n’était pas empoisonnée, l’araignée s’oppose à sa résistance. Si elle réussit, la cible gagne l’affliction Empoisonné et perd 2 points de vie par tour pendant 4 tours."}, {"name": "Embuscade", "text": "L’araignée recluse peut faire une attaque surprise en surgissant du sol, d’un mur ou d’un plafond, s’il ne s’agit pas d’une construction."}]}}$j$::jsonb, 'f43e9cf5-730e-4ede-9b15-1f267d7d7780'),
  ('reine_de_la_couvee', $j$Reine de la couvée$j$, $j${"type": "Créature", "subtype": "Boss", "supertypes": [], "image_url": "", "abilities": [], "creature": {"category": "Bête", "family": "Araignée", "level": 1, "groupDie": "D6", "group": "araignees", "hearts": 3, "armor": 10, "armorMagic": 0, "res": 4, "opres": "D6", "corps": 2, "esprit": 1, "charme": 1, "movement": "marche (sol, mur et plafond)", "speed": "moyenne distance (9 m)", "attacks": {"primary": "8 dégâts perforants", "secondary": "", "tertiary": ""}, "immuneAfflictions": "", "immuneDamage": "", "weakDamage": "", "abilities": [{"name": "Armure naturelle", "text": "Son armure de 10 est une armure naturelle."}, {"name": "Morsure empoisonnée", "text": "Lorsqu’une créature touchée par l’araignée n’était pas empoisonnée, l’araignée s’oppose à sa résistance. Si elle réussit, la cible gagne l’affliction Empoisonné et perd 2 points de vie par tour pendant 4 tours."}, {"name": "Proche de sa couvée", "text": "Lorsque la reine de la couvée subit une attaque, elle lâche 1D4 progénitures araignées proches d’elle."}]}}$j$::jsonb, 'f43e9cf5-730e-4ede-9b15-1f267d7d7780'),
  ('fidele_de_kestian', $j$Fidèle de Kestian$j$, $j${"type": "Créature", "subtype": "Familier", "supertypes": [], "image_url": "", "abilities": [], "creature": {"category": "Bête", "family": "Chien", "level": 0, "groupDie": "D4", "group": "", "hearts": 2, "armor": 0, "armorMagic": 0, "res": 1, "opres": "D4", "corps": 1, "esprit": 3, "charme": 0, "movement": "marche", "speed": "proche", "attacks": {"primary": "Action : 3 dégâts perforants", "secondary": "", "tertiary": ""}, "immuneAfflictions": "", "immuneDamage": "", "weakDamage": "", "abilities": [{"name": "Compagnon", "text": "Niveau égal à celui du joueur. Points de vie : 12 + 2 × niveau."}, {"name": "Protecteur", "text": "Le Fidèle de Kestian peut utiliser votre réaction pour encaisser une attaque à la place d’un allié situé à son contact. Si c’est le cas, échangez ensuite la position de l’allié et du Fidèle de Kestian."}, {"name": "Compagnon de prêtre", "text": "Si votre Fidèle de Kestian vient à mourir, vous pouvez toujours en demander un nouveau à votre temple. Cela dit, il y a peu de chances que ce soit gratuit…"}]}}$j$::jsonb, 'f43e9cf5-730e-4ede-9b15-1f267d7d7780'),
  ('rat_des_paulownias', $j$Rat des paulownias$j$, $j${"type": "Créature", "subtype": "Familier", "supertypes": [], "image_url": "", "abilities": [], "creature": {"category": "Bête", "family": "Rat", "level": 0, "groupDie": "D4", "group": "", "hearts": 1, "armor": 0, "armorMagic": 0, "res": 2, "opres": "D4", "corps": 2, "esprit": 1, "charme": 1, "movement": "marche", "speed": "proche", "attacks": {"primary": "Action : 2 dégâts perforants", "secondary": "", "tertiary": ""}, "immuneAfflictions": "", "immuneDamage": "", "weakDamage": "", "abilities": [{"name": "Compagnon", "text": "Niveau égal à celui du joueur. Points de vie : 6 + 2 × niveau."}, {"name": "Pacte", "text": "Une fois par tour, lorsqu’un rat que vous contrôlez inflige des dégâts à une créature adverse, vous pouvez choisir une carte manœuvre dans la défausse d’un autre joueur et la placer dans votre main.\nEngagement : jouez 3 cartes avec éclosion.\nRécompense : Malédiction de la nuée."}]}}$j$::jsonb, 'f43e9cf5-730e-4ede-9b15-1f267d7d7780'),
  ('ours_brun', $j$Ours brun$j$, $j${"type": "Créature", "subtype": "Familier", "supertypes": [], "image_url": "", "abilities": [], "creature": {"category": "Bête", "family": "Ours", "level": 0, "groupDie": "D4", "group": "", "hearts": 3, "armor": 8, "armorMagic": 0, "res": 2, "opres": "D4", "corps": 4, "esprit": 0, "charme": 0, "movement": "marche", "speed": "proche", "attacks": {"primary": "Action : 8 dégâts tranchants", "secondary": "Action complexe : 6 dégâts tranchants + applique Brisé", "tertiary": ""}, "immuneAfflictions": "", "immuneDamage": "", "weakDamage": "", "abilities": [{"name": "Compagnon", "text": "Niveau égal à celui du joueur. Points de vie : 18 + 2 × niveau."}, {"name": "Combattre sûrement", "text": "Lorsque vous jouez une carte avec éclosion, vous pouvez bannir le premier risque de votre deck."}]}}$j$::jsonb, 'f43e9cf5-730e-4ede-9b15-1f267d7d7780'),
  ('chouette_des_pivoines', $j$Chouette des pivoines$j$, $j${"type": "Créature", "subtype": "Familier", "supertypes": [], "image_url": "", "abilities": [], "creature": {"category": "Bête", "family": "Oiseau", "level": 0, "groupDie": "D4", "group": "", "hearts": 2, "armor": 0, "armorMagic": 0, "res": 2, "opres": "D4", "corps": 2, "esprit": 1, "charme": 1, "movement": "vol", "speed": "proche", "attacks": {"primary": "Action : 3 dégâts perforants", "secondary": "", "tertiary": ""}, "immuneAfflictions": "", "immuneDamage": "", "weakDamage": "", "abilities": [{"name": "Compagnon", "text": "Niveau égal à celui du joueur. Points de vie : 8 + 2 × niveau."}, {"name": "Inspiration florale", "text": "Lorsqu’un allié effectue un test de compétence, vous pouvez l’aider en vous défaussant également d’une carte. Si la carte que vous défaussez possède le sous-type Éclosion, sa valeur est doublée pour ce test."}]}}$j$::jsonb, 'f43e9cf5-730e-4ede-9b15-1f267d7d7780')
